    lockClear: function (k) { delete LOCK[k]; },
    /* 示範版：同一個瀏覽器的分頁共用（學生分頁回報、老師分頁看得到） */
    liveSet: function (code, seat, o) { try { var m = JSON.parse(localStorage.getItem('hatchDemo.live') || '{}'); m[code + ':' + seat] = o; localStorage.setItem('hatchDemo.live', JSON.stringify(m)); } catch (e) {} },
    liveGet: function (code, seats) { var m = {}; try { m = JSON.parse(localStorage.getItem('hatchDemo.live') || '{}'); } catch (e) {} var out = {}; seats.forEach(function (s) { if (m[code + ':' + s]) out[s] = m[code + ':' + s]; }); return out; },
